<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {parseNativeAuthority,projectNativeDirectory} from '$lib/utils/company-authority';
 import {jsonApi} from './identity';
 import Icon from './Icon.svelte';
 import RoomThread from './RoomThread.svelte';
 import CompanyChannelComposer from '$lib/components/company/CompanyChannelComposer.svelte';
 import CompanyChannelNavigation from '$lib/components/company/CompanyChannelNavigation.svelte';
 import CompanyMentions from '$lib/components/company/CompanyMentions.svelte';
 import CompanyTurnActivity from '$lib/components/company/CompanyTurnActivity.svelte';
 import CompanyComputerPanel from '$lib/components/company/CompanyComputerPanel.svelte';
 import {verifiedCompanyTurn,turnFinished,type CompanyTurn} from '$lib/utils/company-turn';
 import FileViewer from './FileViewer.svelte';
 import BotControls from '$lib/components/company/BotControls.svelte';
 import CompanyLivePanel from '$lib/components/company/CompanyLivePanel.svelte';
 import WorkSessions from '$lib/components/company/WorkSessions.svelte';
 import CompanyProviders from '$lib/components/company/CompanyProviders.svelte';
 import CompanyTools from '$lib/components/company/CompanyTools.svelte';
 import AssistantPanelActions from '$lib/components/company/panels/AssistantPanelActions.svelte';
 import NativePanels from '$lib/components/company/panels/NativePanels.svelte';
 import Portrait from './Portrait.svelte';
 import {user} from '$lib/stores';
 import {CompanyClient} from '$lib/utils/company-workspace';
 export let company:any=null;
 export let mode='channel',channel='',refreshKey=0;
 const dispatch=createEventDispatcher();
 let view='messages',error='',accessDenied=false,sendDenied=false,ready=false,name='',email='',busy=false,inviteResult='',creatingChannel=false,channelName='',draft='';
 let rows:any[]=[],files:any[]=[],members:any[]=[],agents:any[]=[],channels:any[]=[],content:Blob|null=null,filename='',cap:any=null;
 const ctrl=new AbortController();let readCtrl=new AbortController(),seq=0,selected='',messageKey='',pendingBody='';
 const base='/api/v1/companies';
 let companyClient:CompanyClient|null=null;
 let messaging:CompanyClient|null=null;
 let selectedAgent='',panels:NativePanels,panelTypes:string[]=[];const openedPanelReceipts=new Set<string>();
 let actorCapabilities:string[]=[],inviteRoles:any[]=[],inviteRole='member',invitationToken='';
 let services={messages:false,sessions:false,roles:false,computer:false},botDispatch=false;
 let mentionedBotIds:string[]=[],turns:Record<string,CompanyTurn>={},turnStarts:Record<string,number>={},readingMessages=false,roomTimer:ReturnType<typeof setInterval>,refreshTimer:ReturnType<typeof setTimeout>;
 let thread:any=null,threadEnabled=false,readEnabled=false,readBusy=false,readError='';
 let dispatchNotes:Record<string,string[]>={};
 function receiptNote(item:any){const name=agents.find(a=>a.id===item.agentId)?.name||'Agent';return name+' · '+(item.status==='SUBMITTED'?'Request submitted':item.started===false?'Request did not start':'Request status unconfirmed');}
 async function markRead(){if(!messaging||readBusy)return;const c=channel,through=Math.max(0,...rows.map(m=>m.sequence));readBusy=true;readError='';
 try{const r=await messaging.request('/rooms/'+encodeURIComponent(c)+'/read','POST',{throughSequence:through});if(c!==channel||ctrl.signal.aborted)return;if(r.id!==c||r.companyId!==company.id||!Number.isSafeInteger(r.unread))throw Error();channels=channels.map(x=>x.id===c?r:x);}
 catch{if(c===channel)readError='Could not update your read position.';}finally{readBusy=false;}}
 let watchingComputer=false,checkingAuthority=false,authorityRevision=0,channelNavigation:CompanyChannelNavigation;
 export function openChannels(){view='messages';watchingComputer=false;void channelNavigation?.focus();}

 function openTab(next:string){if(next==='computer'&&services.messages){view='messages';watchingComputer=!watchingComputer;}else{view=next;watchingComputer=false;}}
 $: companyTabs=[...(services.messages?[['chat','Messages','messages']]:[]),...(services.computer?[['computer','Watch Starli Computer','computer']]:[]),...(services.sessions?[['agents','Bot conversations','sessions']]:[]),...(services.roles?[['settings','Company','apps']]:[])];
 $: eligibleAgents=botDispatch?agents.filter(a=>channels.find(r=>r.id===channel)?.agentIds?.includes(a.id)):[];
 $: inspected=agents.find(a=>a.id===selectedAgent)||agents[0];
 function openToolPanel(action:any){if(!action||openedPanelReceipts.has(action.receiptId)||!panelTypes.includes(action.command?.type))return;openedPanelReceipts.add(action.receiptId);void openResource(action.command);}
 async function openResource(output:any){try{if(!panels)throw Error();await panels.openAssistantPanel(output);}catch{error='This resource could not be opened. Refresh this workspace and try again.';}}
 function panelResult(e:Event){const output=(e as CustomEvent).detail;if(mode==='channel'&&output?.ref?.scope==='company'&&output.ref.ownerId===company?.id)void openResource(output);}
 $: root=company?base+'/'+encodeURIComponent(company.id):'';
 async function load(){
  try{
   if(company){companyClient?.close();messaging?.close();companyClient=new CompanyClient(company.id,()=>localStorage.token||'');messaging=new CompanyClient(company.id,()=>localStorage.token||'',fetch,true);
    const [directory,rooms,scope,roles,messagingCaps,workSessions]=await Promise.allSettled([companyClient.request('/directory','GET',undefined,undefined,true),messaging.request('/rooms'),companyClient.request('/capabilities','GET',undefined,undefined,true),companyClient.request('/roles','GET',undefined,undefined,true),messaging.request('/capabilities'),messaging.request('/work-sessions')]);if(ctrl.signal.aborted)return;
    let verifiedScope=scope.status==='fulfilled'?parseNativeAuthority(scope.value,company.id,$user?.id||''):null;
    if(scope.status==='rejected'&&[401,403,404].includes(scope.reason?.status)){accessLost();return;}
    actorCapabilities=verifiedScope?.capabilities||[];authorityRevision=verifiedScope?.membership_revision||0;
    if(directory.status==='fulfilled'){const people=projectNativeDirectory(directory.value,verifiedScope||parseNativeAuthority(company.scope,company.id,$user?.id||''));members=people.filter((p:any)=>p.kind==='person');agents=people.filter((p:any)=>p.kind==='bot');}
    if(roles.status==='fulfilled')inviteRoles=roles.value.filter((r:any)=>r.kind==='person'&&r.active);
    threadEnabled=messagingCaps.status==='fulfilled'&&messagingCaps.value.threads===true;readEnabled=messagingCaps.status==='fulfilled'&&messagingCaps.value.unread===true;
    services={messages:rooms.status==='fulfilled'&&messagingCaps.status==='fulfilled'&&messagingCaps.value.humanMessaging===true,sessions:workSessions.status==='fulfilled'&&Array.isArray(workSessions.value.sessions),roles:roles.status==='fulfilled',computer:false};
    if(actorCapabilities.includes('computer.view')){try{const desktop=await jsonApi('/api/v1/company-computer/status',ctrl.signal,{headers:{'X-Company-Id':company.id}});if(!ctrl.signal.aborted&&desktop.paired===true&&desktop.company===company.id&&typeof desktop.computer==='string')services={...services,computer:true};}catch{/* Unmounted, unpaired or differently scoped computers have no action. */}}
    botDispatch=messagingCaps.status==='fulfilled'&&messagingCaps.value.nativeBotDispatch===true;
    if(rooms.status==='fulfilled'){channels=rooms.value.rooms.filter((r:any)=>r.kind==='channel'&&r.companyId===company.id);}
    if(directory.status==='rejected'&&rooms.status==='rejected')throw Error('Company service unavailable.');if(!channel&&channels.length)channel=channels[0].id;
   }
   ready=true;if(mode==='channel'&&!companyTabs.some(t=>t[2]===view))view=services.messages?'messages':services.roles?'apps':services.sessions?'sessions':'unavailable';
  }catch{error='Company service unavailable in this environment.';}
 }
 async function mutate(path:string,body:any,key?:string){return jsonApi(path,ctrl.signal,{method:'POST',headers:{'Content-Type':'application/json',...(key?{'Idempotency-Key':key}:{})},body:JSON.stringify(body)});}
 async function create(){busy=true;try{const c=await mutate(base,{name:name.trim()});if(!c.company_id)throw Error();dispatch('created',{id:c.company_id,name:name.trim(),role:'owner'});}catch{error='Company creation could not be confirmed.';}finally{busy=false;}}
 async function invite(){busy=true;try{const d=await mutate(root+'/invites',{user_id:email.trim(),role:inviteRole,ttl:86400});if(!d.token)throw Error();invitationToken=d.token;inviteResult='Invitation created. It expires in 24 hours and works only for the selected account.';email='';}catch{error='Invitation could not be confirmed.';}finally{busy=false;}}
 async function acceptInvite(){if(busy||!invitationToken.trim())return;busy=true;error='';try{const d=await mutate(base+'/invites/accept',{token:invitationToken.trim()});if(d.user_id!==$user?.id||!d.company_id||d.contract_version!==2)throw Error();invitationToken='';dispatch('accepted',{id:d.company_id});}catch{error='This invitation could not be accepted. Check that it belongs to your account and is still valid.';}finally{busy=false;}}
 async function addChannel(){busy=true;try{const c=await messaging!.request('/rooms','POST',{kind:'channel',visibility:'public',name:channelName.trim(),inviteUserIds:[],agentIds:[]},crypto.randomUUID());await load();channel=c.id;creatingChannel=false;channelName='';}catch{error='Channel creation could not be confirmed.';}finally{busy=false;}}
 async function refresh(c:string,v:string){readCtrl.abort();readCtrl=new AbortController();const s=readCtrl.signal,n=++seq;rows=[];files=[];content=null;error='';if(!company||!ready)return;
  try{if(v==='messages'&&c){await readCanonical(c);}
  else if(v==='files'){const r=await companyClient!.request('/files');if(n===seq)files=r.items||[];}}catch{if(!s.aborted)error='This company resource is unavailable.';}
 }
 function mergeMessages(incoming:any[]){const map=new Map(rows.map(m=>[m.id,m]));for(const m of incoming)map.set(m.id,m);rows=[...map.values()].sort((a,b)=>a.sequence-b.sequence).slice(-200);const visible=new Set(rows.map(m=>m.id));turns=Object.fromEntries(Object.entries(turns).filter(([id])=>visible.has(id)));turnStarts=Object.fromEntries(Object.entries(turnStarts).filter(([id])=>visible.has(id)));}
 function turnState(id:string,status:string){if(!turns[id])return;turns={...turns,[id]:{...turns[id],status}};if(turnFinished(status)){delete turnStarts[id];turnStarts={...turnStarts};}}
 async function discoverTurns(c:string){const candidates=rows.filter(m=>m.speaker?.kind==='agent'&&m.runId&&!turns[m.id]).slice(-4);await Promise.allSettled(candidates.map(async m=>{const path='/api/v1/starli/companies/'+encodeURIComponent(company.id)+'/rooms/'+encodeURIComponent(c)+'/bots/'+encodeURIComponent(m.speaker.id)+'/runtime/turns/'+encodeURIComponent(m.runId);const d=await jsonApi(path,readCtrl.signal);if(c!==channel||ctrl.signal.aborted)return;const turn=verifiedCompanyTurn(d,company.id,c,m.id);if(turn){turns={...turns,[m.id]:turn};const source=rows.find(r=>r.id===turn.userMessageId);if(source&&!turnFinished(turn.status))turnStarts[m.id]=source.sequence;}}));}
 async function readCanonical(c:string){if(readingMessages||!messaging||c!==channel||!services.messages)return;readingMessages=true;const epoch=seq;try{const last=Math.max(0,...rows.map(m=>m.sequence||0),channels.find(r=>r.id===c)?.lastMessageSequence||0),starts=Object.values(turnStarts).filter(Number.isSafeInteger);let after=Math.max(0,last-99);if(starts.length)after=Math.min(after,Math.max(0,Math.min(...starts)-1));const room=await messaging.request('/rooms/'+encodeURIComponent(c));if(c!==channel||epoch!==seq||ctrl.signal.aborted)return;if(room.id!==c||room.companyId!==company.id)throw Error('Room scope mismatch');channels=channels.map(r=>r.id===c?room:r);mentionedBotIds=mentionedBotIds.filter(id=>Array.isArray(room.agentIds)&&room.agentIds.includes(id));const incoming:any[]=[];for(let page=0;page<3;page++){const d=await messaging.request('/rooms/'+encodeURIComponent(c)+'/messages?after='+after+'&limit=100');if(c!==channel||epoch!==seq||ctrl.signal.aborted)return;if(!Array.isArray(d.messages)||d.messages.some((m:any)=>m.roomId!==c))throw Error('Message scope mismatch');incoming.push(...d.messages);if(!d.hasMore)break;after=d.next;}mergeMessages(incoming);await discoverTurns(c);}catch(e){if(c===channel&&epoch===seq&&!ctrl.signal.aborted){if([401,403,404].includes(e?.status))accessLost();else error='Channel messages are unavailable.';}}finally{readingMessages=false;}}
 async function pollWorkspace(){if(checkingAuthority||accessDenied||!companyClient||!ready)return;checkingAuthority=true;try{const raw=await companyClient.request('/capabilities','GET',undefined,undefined,true);if(ctrl.signal.aborted)return;const next=parseNativeAuthority(raw,company.id,$user?.id||'');if(next.membership_revision!==authorityRevision&&next.capabilities.includes('messages.send'))sendDenied=false;authorityRevision=next.membership_revision;actorCapabilities=next.capabilities;members=members.map(m=>m.id===next.user_id?{...m,role:next.role}:m);if(view==='messages'&&!document.hidden)await readCanonical(channel);}catch(e){if(!ctrl.signal.aborted&&[401,403,404].includes(e?.status))accessLost();}finally{checkingAuthority=false;}}
 function streamRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{if(view==='messages')void readCanonical(channel);},150);}
 function accessLost(){if(accessDenied)return;accessDenied=true;openedPanelReceipts.clear();ctrl.abort();readCtrl.abort();companyClient?.close();messaging?.close();clearInterval(roomTimer);clearTimeout(refreshTimer);panels?.revokeScope();thread=null;dispatchNotes={};readError='';draft='';pendingBody='';messageKey='';mentionedBotIds=[];selectedAgent='';watchingComputer=false;channel='';invitationToken='';inviteResult='';members=[];agents=[];channels=[];rows=[];files=[];content=null;filename='';turns={};turnStarts={};actorCapabilities=[];panelTypes=[];ready=false;services={messages:false,sessions:false,roles:false,computer:false};error='Company access changed. Reopen your workspace.';window.dispatchEvent(new CustomEvent('starli-company-access-lost',{detail:{companyId:company.id}}));}
 async function send(){if(!draft.trim()||busy||accessDenied||sendDenied||!actorCapabilities.includes('messages.send')||!services.messages||!channel)return;const sentDraft=draft,body=draft.trim(),c=channel,targets=[...new Set(mentionedBotIds)];if(targets.length&&(!botDispatch||targets.some(id=>!eligibleAgents.some(a=>a.id===id)))){error='The selected agent is no longer available.';return;}const fingerprint=JSON.stringify([c,body,targets]);if(fingerprint!==pendingBody){messageKey=crypto.randomUUID();pendingBody=fingerprint;}busy=true;
 try{const d=await messaging!.request('/rooms/'+encodeURIComponent(c)+'/messages','POST',{content:body,parentId:null,mentions:targets.map(id=>({kind:'agent',id})),dispatchAgentIds:targets,attachmentIds:[]},messageKey);if(c!==channel||ctrl.signal.aborted)return;if(d.message?.roomId!==c)throw Error();mergeMessages([d.message]);dispatchNotes={...dispatchNotes,[d.message.id]:(d.botDispatch||[]).map(receiptNote)};for(const entry of d.botDispatch||[]){const turn=verifiedCompanyTurn(entry.receipt,company.id,c);if(turn&&entry.status==='SUBMITTED'){turns={...turns,[turn.assistantMessageId]:turn};if(!turnFinished(turn.status))turnStarts[turn.assistantMessageId]=d.message.sequence;}}if(draft===sentDraft)draft='';pendingBody='';mentionedBotIds=[];await readCanonical(c);}catch(e){if(c===channel&&!ctrl.signal.aborted){if(e?.status===403){sendDenied=true;error='You do not have permission to send to this channel. Your draft is kept.';}else if([401,404].includes(e?.status))accessLost();else error='Message delivery unconfirmed. Refresh before retrying.';}}finally{busy=false;}}
 async function openFile(file:any){const n=++seq,token=localStorage.token;content=null;try{const r=await fetch(root+'/files/'+encodeURIComponent(file.id)+'/content',{headers:{Authorization:'Bearer '+token},signal:readCtrl.signal,cache:'no-store'});if(!r.ok)throw Error();const b=await r.blob();if(n!==seq||ctrl.signal.aborted||localStorage.token!==token)return;content=b;filename=file.name;}catch{if(n===seq)error='File unavailable.';}}
 function change(c:string){thread=null;dispatchNotes={};readError='';sendDenied=false;channel=c;draft='';pendingBody='';mentionedBotIds=[];turns={};turnStarts={};watchingComputer=false;view='messages';}
 function panel(e:Event){if(mode==='channel'){const v=(e as CustomEvent).detail;if(companyTabs.some(t=>t[2]===v))openTab(v);}}
 $: if(ready&&mode==='channel'&&selected!==channel+'|'+view+'|'+refreshKey){selected=channel+'|'+view+'|'+refreshKey;void refresh(channel,view);}
 onMount(()=>{void load();window.addEventListener('company-panel',panel);window.addEventListener('starli-panel-result',panelResult);if(mode==='channel')roomTimer=setInterval(()=>void pollWorkspace(),3000);return()=>{window.removeEventListener('company-panel',panel);window.removeEventListener('starli-panel-result',panelResult);};});onDestroy(()=>{ctrl.abort();readCtrl.abort();companyClient?.close();messaging?.close();clearInterval(roomTimer);clearTimeout(refreshTimer);seq++;});
</script>
{#if thread && view==='messages' && thread.roomId===channel && messaging}{#key thread.id}<RoomThread client={messaging} room={channel} root={thread} directory={[...members,...agents]} on:close={()=>thread=null} on:updated={streamRefresh} on:denied={accessLost}/>{/key}{/if}
{#if mode==='create'}<form on:submit|preventDefault={create}><label>Create a company<input class="sd-input" placeholder="Company name" bind:value={name} maxlength="80" disabled={!ready}/></label><button class="sd-primary" disabled={!ready||busy||!name.trim()}>Create company</button></form>
{:else if mode==='accept'}<form on:submit|preventDefault={acceptInvite}><label>Invitation token<input class="sd-input" type="password" autocomplete="off" bind:value={invitationToken}/></label><button class="sd-button" disabled={!ready||busy||!invitationToken.trim()}>Accept company invitation</button></form>
{:else if mode==='invite'}<h2>Invite people</h2>{#if actorCapabilities.includes('invites.manage')}<form on:submit|preventDefault={invite}><label>Person’s account ID<input class="sd-input" required bind:value={email}/></label><label>Company role<select bind:value={inviteRole}><option value="member">Member</option><option value="admin">Administrator</option>{#each inviteRoles as r}<option value={r.id}>{r.name}</option>{/each}</select></label><button class="sd-primary" disabled={!ready||busy}>Create invitation</button></form>{:else}<p>Company administrators manage invitations.</p>{/if}{#if inviteResult}<p>{inviteResult}</p><label>Invitation token<textarea readonly value={invitationToken} aria-label="Invitation token"/></label>{/if}
{:else if mode==='roster'}<section class="company-directory" aria-label="Company directory"><h3>People ({members.length})</h3>{#each members as m}<div class="member-row"><span class="initial">{m.name?.slice(0,1)||'·'}</span><span><strong>{m.name}</strong><small>{m.role?m.role[0].toUpperCase()+m.role.slice(1):'Person'}</small></span></div>{:else}<p>{ready?'No visible company members.':'Loading people…'}</p>{/each}<h3>Shared company bots ({agents.length})</h3><p class="scope-description">Available to permitted members of {company.name}. Personal agents stay in your personal workspace.</p>{#each agents as a(a.id)}<button class="bot-row" class:inspected={inspected?.id===a.id} aria-pressed={inspected?.id===a.id} on:click={()=>selectedAgent=a.id}><Portrait agent={a} size={36}/><span><strong>{a.name}</strong><small>Shared bot{a.role?' · '+a.role:''}</small></span></button>{:else}<p>{ready?'No shared bots.':'Loading bots…'}</p>{/each}{#if inspected}<div class="agent-inspector">{#key inspected.id}<BotControls companyId={company.id} bot={inspected} audience={{kind:'company',id:company.id,label:company.name+' · company-visible'}}/>{/key}</div>{/if}</section>
{:else}<div class="company-room"><header class="room-header"><div><small>{company?.name}</small>{#if services.messages}<select class="channel-title" aria-label="Company channel" value={channel} on:change={e=>change(e.currentTarget.value)}>{#each channels as c}<option value={c.id}># {c.name}</option>{:else}<option value="">Channels</option>{/each}</select>{:else}<h1 class="channel-title">Company workspace</h1>{/if}</div>{#if ready&&services.messages}<button class="sd-button" on:click={()=>creatingChannel=!creatingChannel}><Icon name="plus" size={15}/>Channel</button>{/if}</header>
 {#if creatingChannel}<form on:submit|preventDefault={addChannel}><input class="sd-input" aria-label="Channel name" bind:value={channelName}/><button disabled={busy||!channelName.trim()}>Create</button></form>{/if}
 <div class="company-content">{#if services.messages}<CompanyChannelNavigation bind:this={channelNavigation} {channels} selected={channel} companyName={company.name} on:select={e=>change(e.detail)}/>{/if}<div class="company-content-main">
 {#if companyTabs.length}<nav aria-label="Company tools">{#each companyTabs as [icon,label,v]}<button class:selected={view===v||v==='computer'&&watchingComputer} aria-current={v!=='computer'&&view===v?'page':undefined} aria-pressed={v==='computer'?watchingComputer||view===v:undefined} on:click={()=>openTab(v)}><Icon name={icon} size={17}/>{label}</button>{/each}</nav>{/if}
 {#if view==='messages'}<div class="channel-body" class:watching={watchingComputer}><div class="log" role="log" aria-label="Channel messages">{#if readEnabled&&rows.length&&channels.find(r=>r.id===channel)?.unread>0}<button class="sd-button" disabled={readBusy} on:click={markRead}>Mark loaded messages as read</button>{/if}{#if readError}<p role="status">{readError}</p>{/if}{#each rows as m(m.id)}<article data-message-id={m.id}><strong>{m.speaker?.kind==='agent'?'AI AGENT BOT · ':''}{[...members,...agents].find(a=>a.id===m.speaker?.id)?.name||m.authorName||(m.speaker?.kind==='agent'?'AI agent':'Team member')}</strong><p>{m.deleted?'Message deleted':m.content}</p>{#if !m.deleted}<AssistantPanelActions message={m} companyId={company.id} availableTypes={panelTypes} on:open={e=>openResource(e.detail)}/>{/if}{#if turns[m.id]}{#key turns[m.id].runId}<CompanyTurnActivity turn={turns[m.id]} on:refresh={streamRefresh} on:state={e=>turnState(m.id,e.detail.status)} on:denied={accessLost} canViewComputer={services.computer} on:computer={()=>watchingComputer=true} on:panel={e=>openToolPanel(e.detail)}/>{/key}{/if}{#if dispatchNotes[m.id]?.length}<ul aria-label="Agent request receipts">{#each dispatchNotes[m.id] as note}<li>{note}</li>{/each}</ul>{/if}{#if threadEnabled&&!m.parentId&&!m.deleted}<button class="thread-link" aria-label={'Open replies to message by '+([...members,...agents].find(a=>a.id===m.speaker?.id)?.name||'team member')} on:click={()=>thread=m}>Thread replies</button>{/if}</article>{:else}{#if ready&&channel}<p>No messages in this channel.</p>{/if}{/each}</div>{#if services.computer&&watchingComputer}<CompanyComputerPanel companyId={company.id} on:close={()=>watchingComputer=false} on:denied={accessLost}/>{/if}</div>
 {#if botDispatch&&channel}<CompanyMentions agents={eligibleAgents} bind:ids={mentionedBotIds} {busy}/>{/if}
 {#if services.messages&&channel}<CompanyChannelComposer bind:draft {busy} eligible={ready && !accessDenied && !sendDenied && actorCapabilities.includes('messages.send') && services.messages && !!channel} on:send={send}/>{#if sendDenied||!actorCapabilities.includes('messages.send')}<p role="status">You can read this channel. Sending requires permission.</p>{/if}{:else if ready}<p class="sd-empty">No company channels are available.</p>{/if}
 {:else if view==='files'}{#each files as f}<button class="sd-list-link" on:click={()=>openFile(f)}><Icon name="files"/>{f.name}</button>{/each}{#if content}<FileViewer blob={content} name={filename}/>{/if}
 {:else if view==='apps'}{#key company.id}<CompanyProviders companyId={company.id} bots={agents}/>{/key}<CompanyTools companyId={company.id} rolesAvailable={services.roles}/>
 {:else if view==='sessions'}<WorkSessions companyId={company.id} people={members} bots={agents}/>
 {:else if view==='computer'}<CompanyComputerPanel companyId={company.id} on:close={()=>view='messages'} on:denied={accessLost}/>
 {:else if view==='tasks'}<CompanyLivePanel companyId={company.id} kind="tasks"/>{:else}<p class="sd-empty">Company services are not connected.</p>{/if}{#if $user?.id}{#key $user.id+':'+company.id}<NativePanels bind:this={panels} bind:availableTypes={panelTypes} userId={$user.id} companyId={company.id}/>{/key}{/if}</div></div></div>{/if}
{#if error}<p class="sd-empty" role="status">{error}</p>{/if}
<style>
.room-header>button{flex:none;white-space:nowrap}.company-content{display:flex;gap:18px;flex:1;min-height:0}.company-content-main{display:flex;flex-direction:column;gap:12px;flex:1;min-width:0;min-height:0}.scope-description{font-size:12px;color:var(--sd-muted);line-height:1.5}@media(max-width:600px){.company-content{flex-direction:column;flex:1;min-height:0}.company-content-main{min-height:0}}


.thread-link{font-size:13px;min-height:36px;color:var(--sd-accent);text-decoration:underline;text-underline-offset:3px}

